define(['local_availabilityhelper/adapter/yui','local_availabilityhelper/analyzer','local_availabilityhelper/scenarios','local_availabilityhelper/ui'],function(Adapter,Analyzer,Scenarios,UI){'use strict';
// This file is part of Moodle - http://moodle.org/

const connect = Adapter.connect;
const analyse = Analyzer.analyse;
const createScenarios = Scenarios.create;


let timer;

/**
 * Starts the availability helper when a core editor exists on the page.
 */
const init = () => {
    connect((tree, editor) => {
        window.clearTimeout(timer);
        timer = window.setTimeout(async() => {
            await UI.initialise(editor);
            const analysis = analyse(tree);
            analysis.scenarios = analysis.incomplete ? null : createScenarios(tree);
            UI.render(editor, analysis);
        }, 350);
    });
};



return {init: init};
});
